import React from "react";
import { AbsoluteFill, Img, useCurrentFrame, interpolate, Easing } from "remotion";
import { COLORS, FONTS, ENGRAVE_SHADOW } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

// Deterministic pseudo-random — stable across frames and renders (no Math.random).
const rnd = (i: number, salt: number): number => {
  const x = Math.sin(i * 127.1 + salt * 311.7) * 43758.5453123;
  return x - Math.floor(x);
};

const ParticleImageAssemble: React.FC<PrimitiveProps> = ({ anim, fps, dark, format, frame }) => {
  const f = useCurrentFrame();
  const D = Math.max(1, Math.round((anim.end - anim.start) * fps));
  const params = anim.params ?? {};
  const src = typeof params.src === "string" ? params.src : "";
  const requested = Number(params.count);
  const count = Math.round(
    Math.min(3000, Math.max(400, Number.isFinite(requested) && requested > 0 ? requested : 1600))
  );
  const text = typeof anim.text === "string" ? anim.text.trim() : "";

  const W = frame.width;
  const H = frame.height;
  // Portrait stacks image over caption; half/landscape lay them out in a row.
  const row = format !== "portrait";
  const side = format === "portrait" ? Math.min(W * 0.72, H * 0.48) : Math.min(H * 0.62, W * 0.42);

  const cols = Math.max(8, Math.round(Math.sqrt(count)));
  const cell = side / cols;
  const dot = Math.max(1.5, cell * 0.42); // really small dots
  const spread = Math.max(W, H) * 0.55;
  const assembleEnd = D * 0.55;

  // Crossfade to the uploaded image once the swarm has settled. No src → swarm stays.
  const reveal = src
    ? interpolate(f, [D * 0.62, D * 0.82], [0, 1], {
        extrapolateLeft: "clamp",
        extrapolateRight: "clamp",
      })
    : 0;
  const particleFade = 1 - reveal;
  const capIn = interpolate(f, [D * 0.5, D * 0.7], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const particles = React.useMemo(() => {
    const palette = [
      COLORS.tealBright,
      COLORS.teal,
      COLORS.teal,
      COLORS.gold,
      COLORS.textOnLight,
      COLORS.leather,
    ];
    return Array.from({ length: cols * cols }, (_, i) => {
      const c = i % cols;
      const r = Math.floor(i / cols);
      const tx = (c + 0.5) * cell + (rnd(i, 1) - 0.5) * cell * 0.6;
      const ty = (r + 0.5) * cell + (rnd(i, 2) - 0.5) * cell * 0.6;
      const ang = rnd(i, 3) * Math.PI * 2;
      const rad = (0.35 + rnd(i, 4)) * spread;
      return {
        tx,
        ty,
        sx: tx + Math.cos(ang) * rad,
        sy: ty + Math.sin(ang) * rad,
        delay: Math.pow(rnd(i, 5), 1.4) * assembleEnd * 0.6,
        travel: Math.max(10, assembleEnd * (0.35 + rnd(i, 6) * 0.25)),
        color: palette[Math.floor(rnd(i, 7) * palette.length) % palette.length],
        size: dot * (0.6 + rnd(i, 8) * 0.8),
        phase: rnd(i, 9) * Math.PI * 2,
      };
    });
  }, [cols, cell, spread, assembleEnd, dot]);

  const radius = side * 0.04;
  const textColor = dark ? COLORS.textOnDark : COLORS.textOnLight;
  const capBase = row ? Math.min(W * 0.045, H * 0.09) : W * 0.055;
  const capSize = Math.min(capBase, (capBase * 24) / Math.max(text.length, 24));

  return (
    <AbsoluteFill style={{ fontFamily: FONTS.display, justifyContent: "center", alignItems: "center" }}>
      <div
        style={{
          display: "flex",
          flexDirection: row ? "row" : "column",
          alignItems: "center",
          gap: side * 0.12,
          maxWidth: W * 0.9,
        }}
      >
        <div style={{ position: "relative", width: side, height: side, flex: "none" }}>
          {particleFade > 0.01 &&
            particles.map((p, i) => {
              const t = interpolate(f, [p.delay, p.delay + p.travel], [0, 1], {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
                easing: Easing.out(Easing.cubic),
              });
              if (t <= 0) {
                return null;
              }
              const x = p.sx + (p.tx - p.sx) * t;
              const y = p.sy + (p.ty - p.sy) * t;
              const twinkle = 0.7 + 0.3 * Math.sin(f * 0.3 + p.phase);
              return (
                <div
                  key={i}
                  style={{
                    position: "absolute",
                    left: x - p.size / 2,
                    top: y - p.size / 2,
                    width: p.size,
                    height: p.size,
                    borderRadius: "50%",
                    backgroundColor: p.color,
                    opacity: t * twinkle * particleFade,
                    boxShadow: `0 0 ${p.size * 2}px ${p.color}55`,
                  }}
                />
              );
            })}
          {src ? (
            <Img
              src={src}
              style={{
                position: "absolute",
                inset: 0,
                width: "100%",
                height: "100%",
                objectFit: "cover",
                borderRadius: radius,
                opacity: reveal,
                boxShadow: `0 0 ${side * 0.12}px ${COLORS.teal}33`,
              }}
            />
          ) : null}
        </div>
        {text ? (
          <div
            style={{
              color: textColor,
              fontWeight: FONTS.displayWeight,
              fontSize: capSize,
              lineHeight: 1.1,
              textTransform: "uppercase",
              letterSpacing: "0.04em",
              textAlign: row ? "left" : "center",
              textShadow: ENGRAVE_SHADOW,
              opacity: capIn,
              maxWidth: row ? W * 0.38 : W * 0.8,
            }}
          >
            {text}
          </div>
        ) : null}
      </div>
    </AbsoluteFill>
  );
};

export default ParticleImageAssemble;

